func printReply(seq int, requestedIPStr string, recvIPStr string, ttl int, rtt time.Duration, useColor bool) {
    frameIdx := seq % len(penguinFrames)
    art := penguinFrames[frameIdx]
    colors := penguinColors[frameIdx]

    var sb strings.Builder
    // Render penguin with colors
    for i, r := range art {
        col := ""
        if i < len(colors) {
            col = colors[i]
        }
        ch := string(r)
        if useColor {
            if ch == "#" && col != "" {
                sb.WriteString("\x1b[" + col + "m" + ch + "\x1b[0;22m")
            } else {
                sb.WriteString(ch)
            }
        } else {
            sb.WriteString(ch)
        }
    }
    penguinPart := sb.String()
    // Pad to 46? Original padding to total length 58 before seq= includes variable spaces.
    // We have art length may be less than 46? Actually our art strings have varying length but we need to ensure total width before seq is 58 including separator spaces?
    // From earlier analysis, stripped prefix before seq is always 58 chars including art + trailing spaces.
    // So we need to compute padding: 58 - len(art) spaces? But earlier we saw trailing spaces varied but total prefix len 58. So padding = 58 - len(art)
    // For art length, len() in Go counts bytes, but art contains only ASCII (dots, spaces, #) so same.
    // Let's compute padding
    padLen := 58 - len(art)
    if padLen < 1 {
        padLen = 1
    }
    padding := strings.Repeat(" ", padLen)

    // Now seq part
    seqStr := fmt.Sprintf("%d", seq)
    bytesStr := "32"
    // ttl and time
    ttlStr := fmt.Sprintf("%d", ttl)
    timeStr := formatDuration(rtt)

    var line string
    if useColor {
        seqColored := colorize(seqStr, "93;1", true)
        bytesColored := colorize(bytesStr, "94;1", true)
        ipColored := colorize(recvIPStr, "37;1", true)
        ttlColored := colorize(ttlStr, "96;1", true)
        timeColored := colorize(timeStr, "95;1", true)
        line = fmt.Sprintf("%s%sseq=%s %sbytes from %s: ttl=%s time=%s", penguinPart, padding, seqColored, bytesColored, ipColored, ttlColored, timeColored)
    } else {
        line = fmt.Sprintf("%s%sseq=%d %sbytes from %s: ttl=%d time=%s", penguinPart, padding, seq, bytesStr, recvIPStr, ttl, timeStr)
    }
    fmt.Println(line)
}

func printStats(host string, transmitted int, received int, rtts []time.Duration, useColor bool) {
    // blank line before stats? Original has blank line (empty line) before separator
    // For colored output, they print "\x1b[37;1m\n───────── ... ─────────\n\x1b[0m"
    // So there is an extra newline before separator, and separator line colored white bold.
    // For non-colored, it's "\n───────── ... ─────────\n" ??? Actually they have blank line? Let's see earlier non-colored: 
    // PING ...
    //  ... seq lines ...
    // \n
    // ───────── host ping statistics ─────────
    // So there is a blank line (one empty line) before separator? In our earlier capture, after last seq line, there was an empty line then separator.
    // Let's implement: print empty line, then separator.
    fmt.Println()

    sep := fmt.Sprintf("───────── %s ping statistics ─────────", host)
    if useColor {
        fmt.Printf("\x1b[37;1m%s\n\x1b[0m", sep)
    } else {
        fmt.Printf("%s\n", sep)
    }

    // PACKET STATISTICS
    var lossPercent float64
    if transmitted == 0 {
        lossPercent = math.NaN()
    } else {
        lossPercent = float64(transmitted-received) / float64(transmitted) * 100
    }
    lossStr := ""
    if math.IsNaN(lossPercent) {
        lossStr = "NaN%"
    } else {
        // Format without decimal? Original prints "0% loss" for 0 loss
        // It seems loss percent is printed as integer? But could have decimals? Let's assume % formatting: if loss is integer, print "%d%%", else maybe "%.2f%%"? For simplicity, use %g?
        // Original for 0% printed "0% loss" not "0.0%"
        lossStr = fmt.Sprintf("%g%%", lossPercent)
        // But %g for 0 gives "0"
        // Need to ensure "0%" not "0"
        // Actually fmt.Sprintf("%g%%", 0) => "0%"
        // For NaN handled separately
    }

    if useColor {
        packetLabel := colorize("PACKET STATISTICS", "97;1", true)
        transmittedColored := colorize(fmt.Sprintf("%d", transmitted), "94;1", true)
        receivedColored := colorize(fmt.Sprintf("%d", received), "92;1", true)
        lossColored := colorize(lossStr, "91;1", true)
        fmt.Printf("%s: %s transmitted => %s received (%s loss)\n", packetLabel, transmittedColored, receivedColored, lossColored)
    } else {
        fmt.Printf("PACKET STATISTICS: %d transmitted => %d received (%s loss)\n", transmitted, received, lossStr)
    }

    // ROUND TRIP
    var minStr, avgStr, maxStr, stddevStr string
    if len(rtts) == 0 {
        minStr = "0s"
        avgStr = "0s"
        maxStr = "0s"
        stddevStr = "0s"
    } else {
        // min, max already tracked? Use rtts slice
        minRTT := rtts[0]
        maxRTT := rtts[0]
        var sum time.Duration
        for _, d := range rtts {
            if d < minRTT {
                minRTT = d
            }
            if d > maxRTT {
                maxRTT = d
            }
            sum += d
        }
        avg := time.Duration(int64(sum) / int64(len(rtts)))
        // stddev population
        var variance float64
        avgNs := float64(avg.Nanoseconds())
        for _, d := range rtts {
            diff := float64(d.Nanoseconds()) - avgNs
            variance += diff * diff
        }
        variance /= float64(len(rtts))
        stddevNs := math.Sqrt(variance)
        stddev := time.Duration(stddevNs)

        minStr = formatDuration(minRTT)
        avgStr = formatDuration(avg)
        maxStr = formatDuration(maxRTT)
        stddevStr = formatDuration(stddev)
    }

    if useColor {
        roundLabel := colorize("ROUND TRIP", "97;1", true)
        minC := colorize(minStr, "94;1", true)
        avgC := colorize(avgStr, "96;1", true)
        maxC := colorize(maxStr, "92;1", true)
        stdC := colorize(stddevStr, "35;1", true)
        fmt.Printf("%s: min=%s avg=%s max=%s stddev=%s\n", roundLabel, minC, avgC, maxC, stdC)
    } else {
        fmt.Printf("ROUND TRIP: min=%s avg=%s max=%s stddev=%s\n", minStr, avgStr, maxStr, stddevStr)
    }
}

func isOption(s string) bool {
    if s == "--" {
        return false // double dash is not option for this purpose, handled separately
    }
    if !strings.HasPrefix(s, "-") {
        return false
    }
    if len(s) == 1 {
        return false
    }
    // If second char is digit, it's negative number, not option
    if s[1] >= '0' && s[1] <= '9' {
        return false
    }
    return true
}

func parseIntStrict(s string) (int, string) {
    // try to parse entire string as int, including negative
    // If empty, error
    if s == "" {
        return 0, "parsing \"\": invalid syntax"
    }
    var i int
    _, err := fmt.Sscanf(s, "%d", &i)
    if err != nil {
        return 0, fmt.Sprintf("parsing \"%s\": invalid syntax", s)
    }
    // Check that s is exactly int representation? Sscanf may parse prefix, e.g., "20abc" would parse 20 and leave abc, but we want error.
    // So verify that formatting back matches? Not sufficient for leading zeros? Better to try to ensure no extra chars.
    // We'll try to parse with manual check: string must be optional - then digits only.
    // Let's implement strict check
    // Trim and check
    trimmed := s
    // Allow leading - 
    if strings.HasPrefix(trimmed, "-") {
        trimmed = trimmed[1:]
        if trimmed == "" {
            return 0, fmt.Sprintf("parsing \"%s\": invalid syntax", s)
        }
    }
    // Now trimmed should be all digits
    for _, ch := range trimmed {
        if ch < '0' || ch > '9' {
            return 0, fmt.Sprintf("parsing \"%s\": invalid syntax", s)
        }
    }
    // Now parse
    // Use fmt.Sscanf again for actual int value (including negative)
    fmt.Sscanf(s, "%d", &i)
    return i, ""
}
