func colorize(s string, code string, useColor bool) string {
 if !useColor || code == "" {
  return s
 }
 return "\x1b[" + code + "m" + s + "\x1b[0;22m"
}

func colorizeErrorLabel(useColor bool) string {
 if !useColor {
  return "[ ERROR ]"
 }
 return "[ \x1b[31;1mERROR\x1b[0;22m ]"
}

func main() {
 args := os.Args[1:]
 count := 20
 privileged := false
 verFlag := false
 helpFlag := false
 hosts := []string{}

 i := 0
 for i < len(args) {
  arg := args[i]

  if arg == "--" {
   for j := i + 1; j < len(args); j++ {
    hosts = append(hosts, args[j])
   }
   break
  }

  if strings.HasPrefix(arg, "--") {
   var name string
   var val *string
   var hasEq bool
   if eqIdx := strings.Index(arg, "="); eqIdx != -1 {
    hasEq = true
    name = arg[:eqIdx]
    v := arg[eqIdx+1:]
    val = &v
   } else {
    name = arg
    hasEq = false
    val = nil
   }

   switch name {
   case "--count":
    if hasEq {
     v := *val
     parsed, perr := parseIntStrict(v)
     if perr != "" {
      first := fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", v)
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     count = parsed
    } else {
     if i+1 >= len(args) {
      first := "expected argument for flag `-c, --count'"
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     nextArg := args[i+1]
     if nextArg == "--" {
      first := "expected argument for flag `-c, --count', but got double dash `--'"
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     if isOption(nextArg) {
      first := fmt.Sprintf("expected argument for flag `-c, --count', but got option `%s'", nextArg)
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     parsed, perr := parseIntStrict(nextArg)
     if perr != "" {
      first := fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", nextArg)
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     count = parsed
     i++
    }
   case "--privilege":
    if hasEq {
     first := "bool flag `-P, --privilege' cannot have an argument"
     fmt.Fprintln(os.Stderr, first)
     fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
     os.Exit(1)
    }
    privileged = true
   case "--version":
    if hasEq {
     first := "bool flag `-V, --version' cannot have an argument"
     fmt.Fprintln(os.Stderr, first)
     fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
     os.Exit(1)
    }
    verFlag = true
   case "--help":
    if hasEq {
     first := "bool flag `-h, --help' cannot have an argument"
     fmt.Fprintln(os.Stderr, first)
     fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
     os.Exit(1)
    }
    helpFlag = true
   default:
    flagName := strings.TrimPrefix(name, "--")
    first := fmt.Sprintf("unknown flag `%s'", flagName)
    fmt.Fprintln(os.Stderr, first)
    fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
    os.Exit(1)
   }
  } else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
   cluster := arg[1:]
   j := 0
   for j < len(cluster) {
    ch := cluster[j]
    switch ch {
    case 'c':
     remaining := cluster[j+1:]
     if remaining != "" {
      if j != 0 {
       first := "expected argument for flag `-c, --count'"
       fmt.Fprintln(os.Stderr, first)
       fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
       os.Exit(1)
      }
      if strings.HasPrefix(remaining, "=") {
       v := remaining[1:]
       _, perr := parseIntStrict(v)
       if perr != "" {
        first := fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", v)
        fmt.Fprintln(os.Stderr, first)
        fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
        os.Exit(1)
       }
       parsed, _ := parseIntStrict(v)
       count = parsed
       j = len(cluster)
       break
      } else {
       _, perr := parseIntStrict(remaining)
       if perr != "" {
        first := fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", remaining)
        fmt.Fprintln(os.Stderr, first)
        fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
        os.Exit(1)
       }
       parsed, _ := parseIntStrict(remaining)
       count = parsed
       j = len(cluster)
       break
      }
     } else {
      if i+1 >= len(args) {
       first := "expected argument for flag `-c, --count'"
       fmt.Fprintln(os.Stderr, first)
       fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
       os.Exit(1)
      }
      nextArg := args[i+1]
      if nextArg == "--" {
       first := "expected argument for flag `-c, --count', but got double dash `--'"
       fmt.Fprintln(os.Stderr, first)
       fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
       os.Exit(1)
      }
      if isOption(nextArg) {
       first := fmt.Sprintf("expected argument for flag `-c, --count', but got option `%s'", nextArg)
       fmt.Fprintln(os.Stderr, first)
       fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
       os.Exit(1)
      }
      _, perr := parseIntStrict(nextArg)
      if perr != "" {
       first := fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", nextArg)
       fmt.Fprintln(os.Stderr, first)
       fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
       os.Exit(1)
      }
      parsed, _ := parseIntStrict(nextArg)
      count = parsed
      i++
      j = len(cluster)
      break
     }
    case 'P':
     remaining := cluster[j+1:]
     if strings.HasPrefix(remaining, "=") {
      first := "bool flag `-P, --privilege' cannot have an argument"
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     privileged = true
     j++
    case 'V':
     remaining := cluster[j+1:]
     if strings.HasPrefix(remaining, "=") {
      first := "bool flag `-V, --version' cannot have an argument"
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     verFlag = true
     j++
    case 'h':
     remaining := cluster[j+1:]
     if strings.HasPrefix(remaining, "=") {
      first := "bool flag `-h, --help' cannot have an argument"
      fmt.Fprintln(os.Stderr, first)
      fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
      os.Exit(1)
     }
     helpFlag = true
     j++
    default:
     first := fmt.Sprintf("unknown flag `%c'", ch)
     fmt.Fprintln(os.Stderr, first)
     fmt.Fprintf(os.Stderr, "%s parse error: %s\n", colorizeErrorLabel(isTerminal(os.Stderr)), first)
     os.Exit(1)
    }
   }
  } else {
   hosts = append(hosts, arg)
  }

  if helpFlag {
   fmt.Print(helpStr)
   os.Exit(0)
  }

  i++
 }

 if verFlag {
  fmt.Print(versionStr)
  os.Exit(0)
 }
 if helpFlag {
  fmt.Print(helpStr)
  os.Exit(0)
 }

 if len(hosts) == 0 {
  useColorErr := isTerminal(os.Stderr)
  fmt.Fprintln(os.Stderr, colorizeErrorLabel(useColorErr)+" must requires an argument")
  os.Exit(1)
 }
 if len(hosts) > 1 {
  useColorErr := isTerminal(os.Stderr)
  fmt.Fprintln(os.Stderr, colorizeErrorLabel(useColorErr)+" too many arguments")
  os.Exit(1)
 }

 host := hosts[0]

 var ip net.IP
 var ipStr string
 var ipVersion int
 parsedIP := net.ParseIP(host)
 var lookupErr error
 if parsedIP != nil {
  ip = parsedIP
  ipStr = ip.String()
  if ip.To4() != nil {
   ipVersion = 4
  } else {
   ipVersion = 6
  }
 } else {
  ips, err := net.LookupIP(host)
  lookupErr = err
  if err != nil {
   useColorErr := isTerminal(os.Stderr)
   fmt.Fprintf(os.Stderr, "%s an error occurred while initializing pinger: failed to init pinger %s\n", colorizeErrorLabel(useColorErr), err.Error())
   os.Exit(0)
  }
  var chosen net.IP
  for _, cand := range ips {
   if cand.To4() != nil {
    chosen = cand
    break
   }
  }
  if chosen == nil && len(ips) > 0 {
   chosen = ips[0]
  }
  if chosen == nil {
   useColorErr := isTerminal(os.Stderr)
   fmt.Fprintf(os.Stderr, "%s an error occurred while initializing pinger: failed to init pinger %s\n", colorizeErrorLabel(useColorErr), lookupErr.Error())
   os.Exit(0)
  }
  ip = chosen
  ipStr = ip.String()
  if ip.To4() != nil {
   ipVersion = 4
  } else {
   ipVersion = 6
  }
 }

 useColorOut := isTerminal(os.Stdout)
 useColorErr := isTerminal(os.Stderr)

 header := fmt.Sprintf("PING %s (%s) type `Ctrl-C` to abort", host, ipStr)
 if useColorOut {
  fmt.Printf("\x1b[97;1m%s\n\x1b[0m", header)
 } else {
  fmt.Printf("%s\n", header)
 }

 sigs := make(chan os.Signal, 1)
 signal.Notify(sigs, syscall.SIGINT, syscall.SIGTERM)
 interrupt := false
 go func() {
  <-sigs
  interrupt = true
 }()

 var conn *icmp.PacketConn
 var connErr error

 if privileged {
  if ipVersion == 4 {
   conn, connErr = icmp.ListenPacket("ip4:icmp", "0.0.0.0")
  } else {
   conn, connErr = icmp.ListenPacket("ip6:ipv6-icmp", "::")
  }
  if connErr != nil {
   fmt.Fprintf(os.Stderr, "%s an error occurred when running ping: %s\n", colorizeErrorLabel(useColorErr), connErr.Error())
   os.Exit(2)
  }
 } else {
  if ipVersion == 4 {
   conn, connErr = icmp.ListenPacket("udp4", "0.0.0.0")
  } else {
   conn, connErr = icmp.ListenPacket("udp6", "::")
  }
  if connErr != nil {
   fmt.Fprintf(os.Stderr, "%s an error occurred when running ping: %s\n", colorizeErrorLabel(useColorErr), connErr.Error())
   os.Exit(2)
  }
 }
 defer func() {
  if conn != nil {
   conn.Close()
  }
 }()

 var p4 *ipv4.PacketConn
 var p6 *ipv6.PacketConn
 if ipVersion == 4 {
  p4 = conn.IPv4PacketConn()
  if p4 != nil {
   p4.SetControlMessage(ipv4.FlagTTL, true)
  }
 } else {
  p6 = conn.IPv6PacketConn()
  if p6 != nil {
   p6.SetControlMessage(ipv6.FlagHopLimit, true)
  }
 }

 infinite := count <= 0
 limit := count
 if infinite {
  limit = math.MaxInt32
 }

 var transmitted int
 var received int
 var rtts []time.Duration

 id := os.Getpid() & 0xffff

 for seq := 0; seq < limit; seq++ {
  if interrupt {
   break
  }
  var wb []byte
  var err error
  if ipVersion == 4 {
   wm := icmp.Message{
    Type: ipv4.ICMPTypeEcho, Code: 0,
    Body: &icmp.Echo{ID: id, Seq: seq, Data: []byte("pingu-payload-24-bytes__")},
   }
   wb, err = wm.Marshal(nil)
  } else {
   wm := icmp.Message{
    Type: ipv6.ICMPTypeEchoRequest, Code: 0,
    Body: &icmp.Echo{ID: id, Seq: seq, Data: []byte("pingu-payload-24-bytes__")},
   }
   wb, err = wm.Marshal(nil)
  }
  if err != nil {
   fmt.Fprintf(os.Stderr, "%s an error occurred when running ping: %s\n", colorizeErrorLabel(useColorErr), err.Error())
   break
  }

  var dst net.Addr
  if privileged {
   if ipVersion == 4 {
    dst, _ = net.ResolveIPAddr("ip4", ipStr)
   } else {
    dst, _ = net.ResolveIPAddr("ip6", ipStr)
   }
  } else {
   if ipVersion == 4 {
    dst, _ = net.ResolveUDPAddr("udp4", ipStr+":0")
   } else {
    dst, _ = net.ResolveUDPAddr("udp6", "["+ipStr+"]:0")
   }
  }

  start := time.Now()
  _, werr := conn.WriteTo(wb, dst)
  if werr != nil {
   printStats(host, transmitted, received, rtts, useColorOut)
   fmt.Fprintf(os.Stderr, "%s an error occurred when running ping: %s\n", colorizeErrorLabel(useColorErr), werr.Error())
   os.Exit(2)
  }
  transmitted++

  conn.SetReadDeadline(time.Now().Add(3 * time.Second))
  if p4 != nil {
   p4.SetReadDeadline(time.Now().Add(3 * time.Second))
  }
  if p6 != nil {
   p6.SetReadDeadline(time.Now().Add(3 * time.Second))
  }

  var ttl int
  var recvIP net.IP
  var rtt time.Duration

  for {
   var buf = make([]byte, 1500)
   var peer net.Addr
   var cm4 *ipv4.ControlMessage
   var cm6 *ipv6.ControlMessage
   var src net.Addr
   var nread int
   var readErr error

   if p4 != nil && ipVersion == 4 {
    nread, cm4, src, readErr = p4.ReadFrom(buf)
    peer = src
    if readErr == nil && cm4 != nil {
     ttl = cm4.TTL
    }
    if privileged && readErr == nil && nread >= 20 {
     if buf[0]>>4 == 4 {
      hdrLen := int(buf[0]&0x0F) * 4
      if nread > hdrLen {
       copy(buf, buf[hdrLen:nread])
       nread = nread - hdrLen
      }
     }
    }
   } else if p6 != nil && ipVersion == 6 {
    nread, cm6, src, readErr = p6.ReadFrom(buf)
    peer = src
    if readErr == nil && cm6 != nil {
     ttl = cm6.HopLimit
    }
   } else {
    nread, peer, readErr = conn.ReadFrom(buf)
    ttl = 64
   }

   if readErr != nil {
    break
   }

   var proto int
   if ipVersion == 4 {
    proto = 1
   } else {
    proto = 58
   }
   rm, err := icmp.ParseMessage(proto, buf[:nread])
   if err != nil {
    continue
   }
   if rm.Type == ipv4.ICMPTypeEchoReply || rm.Type == ipv6.ICMPTypeEchoReply {
    echo, ok := rm.Body.(*icmp.Echo)
    if !ok {
     continue
    }
    if privileged {
     if echo.ID != id {
      continue
     }
     if echo.Seq != seq {
      continue
     }
    } else {
     if echo.Seq != seq {
      continue
     }
    }
    rtt = time.Since(start)
    recvIP = net.ParseIP(ipStr)
    if peer != nil {
     switch v := peer.(type) {
     case *net.IPAddr:
      recvIP = v.IP
     case *net.UDPAddr:
      recvIP = v.IP
     }
    }
    if ttl == 0 {
     ttl = 64
    }
    if recvIP == nil {
     recvIP = ip
    }
    received++
    rtts = append(rtts, rtt)
    printReply(seq, recvIP.String(), ttl, rtt, useColorOut)
    break
   }
  }

  if interrupt {
   break
  }
  if seq < limit-1 {
   time.Sleep(time.Second)
  }
 }

 printStats(host, transmitted, received, rtts, useColorOut)
 os.Exit(0)
}

func printReply(seq int, recvIPStr string, ttl int, rtt time.Duration, useColor bool) {
 frameIdx := seq % len(penguinFrames)
 art := penguinFrames[frameIdx]
 colors := penguinColors[frameIdx]

 var sb strings.Builder
 for i, r := range art {
  col := ""
  if i < len(colors) {
   col = colors[i]
  }
  ch := string(r)
  if useColor {
   if ch == "#" && col != "" {
    sb.WriteString("\x1b[" + col + "m" + ch + "\x1b[0;22m")
   } else {
    sb.WriteString(ch)
   }
  } else {
   sb.WriteString(ch)
  }
 }
 penguinPart := sb.String()
 padLen := 58 - len(art)
 if padLen < 1 {
  padLen = 1
 }
 padding := strings.Repeat(" ", padLen)

 seqStr := fmt.Sprintf("%d", seq)
 bytesStr := "32"
 ttlStr := fmt.Sprintf("%d", ttl)
 timeStr := rtt.String()

 var line string
 if useColor {
  seqColored := colorize(seqStr, "93;1", true)
  bytesColored := colorize(bytesStr, "94;1", true)
  ipColored := colorize(recvIPStr, "37;1", true)
  ttlColored := colorize(ttlStr, "96;1", true)
  timeColored := colorize(timeStr, "95;1", true)
  line = fmt.Sprintf("%s%sseq=%s %sbytes from %s: ttl=%s time=%s", penguinPart, padding, seqColored, bytesColored, ipColored, ttlColored, timeColored)
 } else {
  line = fmt.Sprintf("%s%sseq=%d %sbytes from %s: ttl=%d time=%s", penguinPart, padding, seq, bytesStr, recvIPStr, ttl, timeStr)
 }
 fmt.Println(line)
}

func printStats(host string, transmitted int, received int, rtts []time.Duration, useColor bool) {
 sep := fmt.Sprintf("───────── %s ping statistics ─────────", host)
 if useColor {
  fmt.Printf("\x1b[37;1m\n%s\n\x1b[0m", sep)
 } else {
  fmt.Printf("\n%s\n", sep)
 }

 var lossPercent float64
 if transmitted == 0 {
  lossPercent = math.NaN()
 } else {
  lossPercent = float64(transmitted-received) / float64(transmitted) * 100
 }
 lossStr := ""
 if math.IsNaN(lossPercent) {
  lossStr = "NaN%"
 } else {
  lossStr = fmt.Sprintf("%g%%", lossPercent)
 }

 if useColor {
  packetLabel := colorize("PACKET STATISTICS", "97;1", true)
  transmittedColored := colorize(fmt.Sprintf("%d", transmitted), "94;1", true)
  receivedColored := colorize(fmt.Sprintf("%d", received), "92;1", true)
  lossColored := colorize(lossStr, "91;1", true)
  fmt.Printf("%s: %s transmitted => %s received (%s loss)\n", packetLabel, transmittedColored, receivedColored, lossColored)
 } else {
  fmt.Printf("PACKET STATISTICS: %d transmitted => %d received (%s loss)\n", transmitted, received, lossStr)
 }

 var minStr, avgStr, maxStr, stddevStr string
 if len(rtts) == 0 {
  minStr = "0s"
  avgStr = "0s"
  maxStr = "0s"
  stddevStr = "0s"
 } else {
  minRTT := rtts[0]
  maxRTT := rtts[0]
  var sum time.Duration
  for _, d := range rtts {
   if d < minRTT {
    minRTT = d
   }
   if d > maxRTT {
    maxRTT = d
   }
   sum += d
  }
  avg := time.Duration(int64(sum) / int64(len(rtts)))
  var variance float64
  avgNs := float64(avg.Nanoseconds())
  for _, d := range rtts {
   diff := float64(d.Nanoseconds()) - avgNs
   variance += diff * diff
  }
  variance /= float64(len(rtts))
  stddevNs := math.Sqrt(variance)
  stddev := time.Duration(stddevNs)

  minStr = minRTT.String()
  avgStr = avg.String()
  maxStr = maxRTT.String()
  stddevStr = stddev.String()
 }

 if useColor {
  roundLabel := colorize("ROUND TRIP", "97;1", true)
  minC := colorize(minStr, "94;1", true)
  avgC := colorize(avgStr, "96;1", true)
  maxC := colorize(maxStr, "92;1", true)
  stdC := colorize(stddevStr, "35;1", true)
  fmt.Printf("%s: min=%s avg=%s max=%s stddev=%s\n", roundLabel, minC, avgC, maxC, stdC)
 } else {
  fmt.Printf("ROUND TRIP: min=%s avg=%s max=%s stddev=%s\n", minStr, avgStr, maxStr, stddevStr)
 }
}

func isOption(s string) bool {
 if s == "--" {
  return false
 }
 if !strings.HasPrefix(s, "-") {
  return false
 }
 if len(s) == 1 {
  return false
 }
 if s[1] >= '0' && s[1] <= '9' {
  return false
 }
 return true
}

func parseIntStrict(s string) (int, string) {
 if s == "" {
  return 0, "parsing \"\": invalid syntax"
 }
 trimmed := s
 if strings.HasPrefix(trimmed, "-") {
  trimmed = trimmed[1:]
  if trimmed == "" {
   return 0, fmt.Sprintf("parsing \"%s\": invalid syntax", s)
  }
 }
 for _, ch := range trimmed {
  if ch < '0' || ch > '9' {
   return 0, fmt.Sprintf("parsing \"%s\": invalid syntax", s)
  }
 }
 var i int
 fmt.Sscanf(s, "%d", &i)
 return i, ""
}
